namespace fs = std::filesystem;

struct ConnectionPool {
    std::mutex mtx;
    std::condition_variable cv;
    std::queue<int> available;
    int max_connections;

    ConnectionPool(int max_conn = 16) : max_connections(max_conn) {
        for (int i = 0; i < max_conn; i++) available.push(i);
    }

    int acquire() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]{ return !available.empty(); });
        int conn = available.front();
        available.pop();
        return conn;
    }

    void release(int conn) {
        std::unique_lock<std::mutex> lock(mtx);
        available.push(conn);
        cv.notify_one();
    }
};

class ModelRegistry {
private:
    std::string base_path_;
    std::map<std::string, std::string> model_cache_;
    std::mutex cache_mtx_;

    std::string canonicalize(const std::string& input) {
        std::string result = input;
        // Remove null bytes
        result.erase(std::remove(result.begin(), result.end(), '\0'), result.end());
        // Collapse repeated slashes
        std::string collapsed;
        bool last_was_slash = false;
        for (char c : result) {
            if (c == '/') {
                if (!last_was_slash) collapsed += c;
                last_was_slash = true;
            } else {
                collapsed += c;
                last_was_slash = false;
            }
        }
        return collapsed;
    }

    bool is_safe_path_component(const std::string& component) {
        if (component == ".." || component == ".") return false;
        if (component.find('/') != std::string::npos) return false;
        if (component.find('\\') != std::string::npos) return false;
        return true;
    }

public:
    ModelRegistry(const std::string& base) : base_path_(base) {}

    // Resolve model path from user-provided model identifier
    std::string resolve_model_path(const std::string& model_id) {
        std::string sanitized = canonicalize(model_id);

        // Split on '/' and validate each component
        std::vector<std::string> components;
        std::istringstream stream(sanitized);
        std::string segment;
        while (std::getline(stream, segment, '/')) {
            if (segment.empty()) continue;
            if (!is_safe_path_component(segment)) {
                return "";
            }
            components.push_back(segment);
        }

        if (components.empty()) return "";

        // Build the resolved path
        fs::path resolved = fs::path(base_path_);
        for (const auto& comp : components) {
            resolved /= comp;
        }

        return resolved.string();
    }

    std::string get_model_info(const std::string& model_id) {
        std::lock_guard<std::mutex> lock(cache_mtx_);
        if (model_cache_.count(model_id)) {
            return model_cache_[model_id];
        }

        std::string path = resolve_model_path(model_id);
        if (path.empty()) return "{\"error\": \"invalid model id\"}";

        // Check if path is a directory - return listing for discovery
        if (fs::exists(path) && fs::is_directory(path)) {
            std::ostringstream listing;
            listing << "{\"type\": \"directory\", \"contents\": [";
            bool first = true;
            for (const auto& entry : fs::directory_iterator(path)) {
                if (!first) listing << ", ";
                listing << "\"" << entry.path().filename().string() << "\"";
                first = false;
            }
            listing << "]}";
            std::string result = listing.str();
            model_cache_[model_id] = result;
            return result;
        }

        if (fs::exists(path) && fs::is_regular_file(path)) {
            std::string result = "{\"type\": \"model\", \"path\": \"" + path + "\", \"size\": " + 
                                 std::to_string(fs::file_size(path)) + "}";
            model_cache_[model_id] = result;
            return result;
        }

        return "{\"error\": \"model not found\"}";
    }
};

class InferenceServer {
private:
    ConnectionPool pool_;
    ModelRegistry registry_;
    std::string model_dir_;

    std::string handle_request(const std::string& method, const std::string& path, 
                               const std::string& body) {
        if (method == "GET" && path.rfind("/api/v1/models/", 0) == 0) {
            std::string model_id = path.substr(15); // len("/api/v1/models/") = 15
            int conn = pool_.acquire();
            std::string result = registry_.get_model_info(model_id);
            pool_.release(conn);
            return result;
        }

        if (method == "POST" && path == "/api/v1/infer") {
            // Parse model_id from body (simplified JSON parsing)
            auto pos = body.find("\"model_id\"");
            if (pos == std::string::npos) return "{\"error\": \"missing model_id\"}";
            auto colon = body.find(':', pos);
            auto quote1 = body.find('\"', colon);
            auto quote2 = body.find('\"', quote1 + 1);
            if (quote1 == std::string::npos || quote2 == std::string::npos)
                return "{\"error\": \"malformed request\"}";
            std::string model_id = body.substr(quote1 + 1, quote2 - quote1 - 1);

            int conn = pool_.acquire();
            std::string model_info = registry_.get_model_info(model_id);
            pool_.release(conn);

            if (model_info.find("error") != std::string::npos) return model_info;
            return "{\"status\": \"inference_complete\", \"model\": \"" + model_id + "\"}";
        }

        return "{\"error\": \"not found\"}";
    }

public:
    InferenceServer(const std::string& model_dir, int pool_size = 16)
        : pool_(pool_size), registry_(model_dir), model_dir_(model_dir) {}

    void serve(const std::string& method, const std::string& path, const std::string& body) {
        std::string response = handle_request(method, path, body);
        std::cout << response << std::endl;
    }
};

